const DB = 'REPLACE_WITH_NOTION_TASKS_DB_ID';
const out = [];
for (const item of $input.all()) {
  const t = item.json;
  const props = {
    Name:   { title: [ { text: { content: (t.title || 'Untitled task').slice(0, 200) } } ] },
    Status: { select: { name: t.status || 'open' } },
  };
  if (t.due_date)     props.Due      = { date: { start: t.due_date } };
  if (t.priority)     props.Priority = { select: { name: t.priority } };
  if (t.created_from) props.Source   = { select: { name: t.created_from } };
  if (t.description)  props.Notes    = { rich_text: [ { text: { content: (t.description || '').slice(0, 1900) } } ] };
  const hasPage = !!t.notion_page_id;
  const method = hasPage ? 'PATCH' : 'POST';
  const url = hasPage ? ('https://api.notion.com/v1/pages/' + t.notion_page_id)
                      : 'https://api.notion.com/v1/pages';
  const body = hasPage ? { properties: props }
                       : { parent: { database_id: DB }, properties: props };
  out.push({ json: { task_id: t.id, method: method, url: url, body: body } });
}
return out;

const prep = $('Prep Notion call').all();
const resp = $input.all();
const out = [];
for (let i = 0; i < resp.length; i++) {
  const task_id = prep[i] ? prep[i].json.task_id : null;
  const r = resp[i] ? resp[i].json : {};
  const page_id = r.id || null;
  if (task_id && page_id) out.push({ json: { task_id: task_id, page_id: page_id } });
}
return out;
